script:
import time, json, re

URL = "https://tong.com.vn/dat-ban"
DEFAULT_BRANCH_VALUE = "609cca4ad17c02589ad1ec98"  # chi nhánh trong code cũ
TIMEOUT = 15.0
POLL = 0.15
DAY_LABELS = {0: "hôm nay", 1: "ngày mai", 2: "ngày kia"}


def _j(v):
    return json.dumps(v, ensure_ascii=False)


def _norm(s):
    return re.sub(r"\s+", " ", str(s if s is not None else "")).strip().casefold()


def _sleep(t):
    time.sleep(t)


def _wait_until(fn, timeout=TIMEOUT):
    end = time.time() + timeout
    while True:
        r = fn()
        if r:
            return r
        if time.time() >= end:
            return None
        _sleep(POLL)


def _select_info(sel_id):
    return js(f"""return (() => {{
        const s = document.getElementById({_j(sel_id)});
        if (!s) return null;
        return {{
            disabled: s.disabled,
            value: s.value,
            opts: [...s.options].map((o, i) => ({{i: i, v: o.value, t: o.text.trim(), d: o.disabled}}))
        }};
    }})();""")


def _apply_select(sel_id, idx):
    return js(f"""return (() => {{
        const s = document.getElementById({_j(sel_id)});
        s.selectedIndex = {int(idx)};
        s.dispatchEvent(new Event('input', {{bubbles: true}}));
        s.dispatchEvent(new Event('change', {{bubbles: true}}));
        return s.value;
    }})();""")


def _pick(sel_id, label, matcher):
    info = _select_info(sel_id)
    if info is None:
        raise RuntimeError(f"UNAVAILABLE: không tìm thấy ô {label}")
    if info["disabled"]:
        raise RuntimeError(f"UNAVAILABLE: ô {label} đang bị khóa")
    hits = [o for o in info["opts"] if matcher(o["v"], o["t"])]
    if not hits:
        raise RuntimeError(f"UNAVAILABLE: không có lựa chọn đúng cho {label}")
    if len(hits) > 1:
        raise RuntimeError(f"UNAVAILABLE: lựa chọn {label} không rõ ràng ({len(hits)} kết quả)")
    o = hits[0]
    if o["d"]:
        raise RuntimeError(f"UNAVAILABLE: lựa chọn {label} '{o['t']}' bị disabled")
    _apply_select(sel_id, o["i"])
    return o["v"], o["t"]


def _m_branch(v, t):
    if BRANCH is None:
        return v == DEFAULT_BRANCH_VALUE
    return _norm(t) == _norm(BRANCH)


def _m_party(v, t):
    return _norm(t) == str(PARTY) or v == str(PARTY)


def _m_day(v, t):
    nt = _norm(t)
    lab = DAY_LABELS.get(DAY_OFFSET)
    return (lab is not None and nt == lab) or nt == _norm(DATE_DMY) or v == DATE_ISO


def _m_hour(v, t):
    if _norm(t) == _norm(HHMM):
        return True
    return bool(re.fullmatch(r"\d{2}:\d{2}(:\d{2})?", v or "")) and v[:5] == HHMM


def _hours_snapshot():
    info = _select_info("selectHour")
    if info is None:
        return None
    sig = tuple((o["v"], o["t"], o["d"]) for o in info["opts"])
    return {"sig": sig, "n": len(sig), "disabled": info["disabled"]}


def _wait_hours_stable(min_wait=0.8, stable_for=0.6):
    # min_wait: chờ để trang kịp bắt đầu tải lại danh sách giờ sau khi đổi chi nhánh/số người/ngày
    t0 = time.time()
    end = t0 + TIMEOUT
    last_sig = None
    since = t0
    while time.time() < end:
        snap = _hours_snapshot()
        now = time.time()
        if snap is None:
            raise RuntimeError("UNAVAILABLE: không thấy danh sách giờ")
        if snap["sig"] != last_sig:
            last_sig = snap["sig"]
            since = now
        elif (now - t0 >= min_wait and now - since >= stable_for
              and snap["n"] > 1 and not snap["disabled"]):
            return snap
        _sleep(POLL)
    raise RuntimeError("UNAVAILABLE: danh sách giờ không ổn định trong 15 giây")


def _fill(selector, text):
    pos = js(f"""return (() => {{
        const e = document.querySelector({_j(selector)});
        if (!e) return null;
        e.scrollIntoView({{block: 'center'}});
        const r = e.getBoundingClientRect();
        return {{x: r.left + r.width / 2, y: r.top + r.height / 2}};
    }})();""")
    if pos is None:
        return False
    click_at_xy(pos["x"], pos["y"])
    js(f"""return (() => {{
        const e = document.querySelector({_j(selector)});
        e.focus();
        e.select();
        return true;
    }})();""")
    press_key("Backspace")
    type_text(text)
    return True


def _read_all():
    return js("""return (() => {
        const q = (sel) => { const e = document.querySelector(sel); return e ? e.value : null; };
        const d = document.getElementById('selectDay');
        return {
            branch: q('#selectCoso'),
            party: q('#selectSoNguoi'),
            day: q('#selectDay'),
            dayText: (d && d.selectedOptions[0]) ? d.selectedOptions[0].text.trim() : null,
            hour: q('#selectHour'),
            name: q('#nameOrder'),
            phone: q('#sdtOrder'),
            email: q('input[type=email]')
        };
    })();""")


# ---------------- MAIN ----------------

goto_url(URL)
wait_for_load()

if _wait_until(lambda: _select_info("selectHour") is not None) is None:
    raise RuntimeError("UNAVAILABLE: trang chưa có form đặt bàn")

# 1) Chọn chi nhánh, số người, ngày TRƯỚC (các thay đổi này có thể tải lại danh sách giờ)
expect = {}
expect["branch"] = _pick("selectCoso", "chi nhánh", _m_branch)
expect["party"] = _pick("selectSoNguoi", "số người", _m_party)
expect["day"] = _pick("selectDay", "ngày", _m_day)

# 2) Chờ danh sách giờ ổn định rồi mới chọn giờ
_wait_hours_stable()
expect["hour"] = _pick("selectHour", "giờ", _m_hour)

# 3) Điền thông tin liên hệ
if not _fill("#nameOrder", NAME):
    raise RuntimeError("UNAVAILABLE: không thấy ô tên")
if not _fill("#sdtOrder", PHONE):
    raise RuntimeError("UNAVAILABLE: không thấy ô số điện thoại")

email_filled = False
if EMAIL:
    email_filled = _fill('input[type=email]', EMAIL)  # không có ô email thì bỏ qua

# 4) Đọc lại giá trị thật và kiểm tra
vals = _read_all()
problems = []


def _chk(label, got, want):
    if got != want:
        problems.append(f"{label}: đang '{got}', cần '{want}'")


_chk("chi nhánh", vals["branch"], expect["branch"][0])
_chk("số người", vals["party"], expect["party"][0])
_chk("ngày", vals["day"], expect["day"][0])
_chk("ngày (hiển thị)", vals["dayText"], expect["day"][1])
_chk("giờ", vals["hour"], expect["hour"][0])
_chk("tên", vals["name"], NAME)
_chk("số điện thoại", vals["phone"], PHONE)
if email_filled:
    _chk("email", vals["email"], EMAIL)

if problems:
    raise RuntimeError("MISMATCH: " + "; ".join(problems))

print({
    "branch": vals["branch"],
    "party": vals["party"],
    "day": vals["dayText"],
    "hour": vals["hour"],
    "name": vals["name"],
    "phone": vals["phone"],
    "email": vals["email"],
})
